          'Задание 2. Укажите варианты ответов, в которых верно определена грамматическая основа в одном из предложений или в одной из частей сложного предложения текста:',
        options: [
          'рассказать (предложение 1)',
          'первооткрыватель (предложение 2)',
          'прокладывает путь (предложение 3)',
          'это демонстрирует (предложение 4)',
          'я уяснил (предложение 5)',
        ],
