passage:
'(1)Хотя идея построить судно, которое будет погружаться под воду и всплывать по желанию экипажа, достаточно стара, первые действующие подводные лодки появились только в XIX веке. (2)Тогда же, во время гражданской войны в США, состоялась и первая удачная атака подводной лодкой надводного корабля. (3)А в начале XX века появились технологии, позволившие таким лодкам выходить в открытое море, погружаться на несколько часов под воду и из глубины наносить торпедные удары по кораблям, находящимся на поверхности. (4)Уже в начале Первой мировой войны новый вид морского вооружения заставил весь мир обратить на себя внимание: немецкая подлодка в течение получаса пустила ко дну сразу три английских крейсера. (5)Это казалось невероятным: маленький кораблик с немногочисленным экипажем потопил три огромных военных судна, которые обслуживали сотни людей!',
